              cf[c]["r_prime_own_miller_rabin_80_bases"], "hasse", cf[c]["hasse_interval_holds"], "rho", s(rho[c], 20))
    print("m* (KR-A, PF-2, omega 3):", mstar, "C_I:", s(ci_v, 20), "runner-up:", ru0, "gap:", s(gap0, 10))
    print("Table-1 control, PF-2 truncated matches:", sum(1 for x in ctl if x["PF2_trunc_matches"]), "of", len(ctl))
    print("Q3 rows:", {k: len(v) for k, v in q3.items()}, "QX rows:", len(qx), "QA rows:", len(qa))
    print("third forms:", res["QA_third_form_max_abs_dev_from_PF2"],
