#!/usr/local/bin/python3
"""TASK-20261002-16c2f1, joint J11 -- IMPLEMENTATION II (disjoint numeric lineage).

Python `decimal` (libmpdec) at 80 digits; no mpmath, no sympy. Its own FIPS
parser (character filter rather than line asserts), its own binomial
recurrence (no math.comb), pi by Machin's formula, its own series for
1 - exp(-x). Recomputes rho, A (PF-1, PF-2, both k readings), the Q3 tables at
omega 3.0 and 2.376, the QX crossovers and C_I at every NF degree, and emits the
same flat key set as implementation I for comparison.
"""
import json
import sys
from decimal import Decimal, getcontext

getcontext().prec = 80
D_ = Decimal
OUT = sys.argv[1]
FIPS = "/home/user/crypto-autoresearcher/inputs/FIPS186-4-BINARY-CURVES/fips186-4_text.md"
N = 571


def fips_order(text, heading):
    i = text.index(heading)
    j = text.index("n =", i)
    k = text.index("Polynomial Basis", j)
    return int("".join(ch for ch in text[j + 3:k] if ch.isdigit()))


def arctan_inv(x):
    # arctan(1/x) by its Taylor series
    x = D_(x)
    x2 = x * x
    term = D_(1) / x
    total = term
    n = 1
    sign = -1
    eps = D_(10) ** (-(getcontext().prec + 5))
    while True:
        term = term / x2
        t = term / (2 * n + 1)
        if t < eps:
            break
        total += sign * t
        sign = -sign
        n += 1
    return total


PI = 16 * arctan_inv(5) - 4 * arctan_inv(239)
LN2 = D_(2).ln()


def lg(x):
    return D_(x).ln() / LN2


def one_minus_exp_neg(x):
    x = D_(x)
    if x < D_("0.5"):
        # x - x^2/2! + x^3/3! - ...
        total = D_(0)
        term = x
        k = 1
        eps = D_(10) ** (-(getcontext().prec + 5))
        while abs(term) > eps * abs(x):
            total += term
            k += 1
            term = -term * x / k
        return total
    return 1 - (-x).exp()


def fact(m):
    r = 1
    for i in range(2, m + 1):
        r *= i
    return r


def kval(n, m, kr):
    if kr == "KR-A":
        return D_(n) / D_(m), 0
    k = (n + m - 1) // m
    return D_(k), m * k - n


def A(n, m, kr, pf):
    k, e = kval(n, m, kr)
    x = D_(2) ** e / D_(fact(m))
    if pf == "PF-1":
        return k - lg(x)
    return k - lg(one_minus_exp_neg(x))


_bp = {}


def binom_prefix_list(nn, Dmax):
    key = (nn, Dmax)
    if key not in _bp:
        out = []
        c = 1
        acc = 0
        for d in range(0, Dmax + 1):
            if d > 0:
                c = c * (nn - d + 1) // d
            acc += c
            out.append(acc)
        _bp[key] = out
    return _bp[key]


def W(nn, D):
    return lg(binom_prefix_list(nn, 64)[D])


L2N = lg(N)


def SR(R, D, om):
    if R == "R-B":
        return D * om * L2N
    return om * (W(N, D) - W(N, 4) + 4 * L2N)


def fmt(x, digits=40):
    return format(x, "." + str(digits) + "g") if False else str(+x)


def main():
    text = open(FIPS, encoding="utf-8").read()
    rK = fips_order(text, "D.1.3.5.1  Curve K-571")
    rB = fips_order(text, "D.1.3.5.2  Curve B-571")
    rho = {"K-571": D_("0.5") * lg(PI * rK / (4 * 571)), "B-571": D_("0.5") * lg(PI * rB / 4)}
    flat = {}
    flat["rho|K-571"] = rho["K-571"]
    flat["rho|B-571"] = rho["B-571"]
    for m in range(2, 31):
        for kr in ("KR-A", "KR-B"):
            for pf in ("PF-1", "PF-2"):
                flat["A|%s|%s|%d" % (kr, pf, m)] = A(N, m, kr, pf)
    for om_lbl in ("3.0", "2.376"):
        om = D_(om_lbl)
        for c in ("K-571", "B-571"):
            for R in ("R-B", "R-M"):
                for kr in ("KR-A", "KR-B"):
                    for pf in ("PF-1", "PF-2"):
                        for m in range(2, 31):
                            a = A(N, m, kr, pf)
                            key = "Q3|%s|%s|%s|%s|%s|%d" % (om_lbl, c, R, kr, pf, m)
                            marg = [None] + [a + SR(R, D, om) - rho[c] for D in range(1, 65)]
                            ds = next((D for D in range(2, 65) if marg[D] > 0), None)
                            if ds is None:
                                flat[key + "|Dstar"] = "no crossing at D <= 64"
                            elif ds == 2:
                                flat[key + "|Dstar"] = "D* <= 2"
                            else:
                                flat[key + "|Dstar"] = ds
                                flat[key + "|mlo"] = marg[ds - 1]
                                flat[key + "|mhi"] = marg[ds]
                            if R == "R-B":
                                flat[key + "|Dreal6"] = ((rho[c] - a) / (om * L2N)).quantize(D_("0.000001"), rounding="ROUND_HALF_UP")
    for m in range(2, 31):
        for kr in ("KR-A", "KR-B"):
            if kr == "KR-A":
                nn = (m - 1) * N
            else:
                nn = (m - 2) * N + m * ((N + m - 1) // m)
            key = "QX|%s|%d" % (kr, m)
            flat[key + "|N5"] = nn
            g = {D: W(nn, D) - W(nn, D - 1) for D in range(5, 65)}
            dl = {D: (W(nn, D) - W(nn, 4)) - (D - 4) * L2N for D in range(4, 65)}
            dps = next((D for D in range(5, 65) if g[D] < L2N), None)
            dcum = next((D for D in range(5, 65) if dl[D] < 0), None)
            flat[key + "|Dps"] = dps if dps is not None else "none in 5..64"
            flat[key + "|Dcum"] = dcum if dcum is not None else "none in 5..64"
            mx = max(dl.values())
            flat[key + "|max"] = mx
            flat[key + "|argmax"] = min(D for D in dl if dl[D] == mx)
    degs = sorted(set([79, 89, 97, 109, 131, 155, 163, 185, 191, 233, 239, 283, 359, 409, 571]))
    for n in degs:
        for kr in ("KR-A", "KR-B"):
            for pf in ("PF-1", "PF-2"):
                vals = [(A(n, m, kr, pf) + 4 * 3 * lg(n), m) for m in range(2, min(30, n) + 1)]
                bv, bm = vals[0]
                for v, m in vals[1:]:
                    if v < bv:
                        bv, bm = v, m
                rest = [x for x in vals if x[1] != bm]
                rv, rm = rest[0]
                for v, m in rest[1:]:
                    if v < rv:
                        rv, rm = v, m
                flat["CI|%d|%s|%s|val" % (n, kr, pf)] = bv
                flat["CI|%d|%s|%s|argmin" % (n, kr, pf)] = bm
                flat["CI|%d|%s|%s|runner" % (n, kr, pf)] = rm
    out = {k: (str(v) if isinstance(v, Decimal) else v) for k, v in flat.items()}
    with open(OUT, "w") as fh:
        json.dump({"implementation": "II (decimal/libmpdec, 80 digits)", "flat": out,
                   "pi_digits": str(PI)[:42], "rK_bits": rK.bit_length(), "rB_bits": rB.bit_length()}, fh, indent=1)
    print("II done:", len(out), "keys; rK bits", rK.bit_length(), "rB bits", rB.bit_length())


if __name__ == "__main__":
    main()

