#!/usr/local/bin/python3
"""Compare implementation I (mpmath) with implementation II (decimal) key by key."""
import json
import sys
from decimal import Decimal, getcontext

getcontext().prec = 80
a = json.load(open(sys.argv[1]))["flat"]
b = json.load(open(sys.argv[2]))["flat"]
out = {"keys_I": len(a), "keys_II": len(b), "keys_only_in_I": sorted(set(a) - set(b))[:20],
       "keys_only_in_II": sorted(set(b) - set(a))[:20], "exact_mismatches": [], "max_abs_diff_by_kind": {}}
for k in sorted(set(a) & set(b)):
    va, vb = a[k], b[k]
    kind = k.split("|")[0] + "|" + k.split("|")[-1]
    if isinstance(va, (int,)) or isinstance(vb, (int,)) or k.endswith(("Dstar", "Dps", "Dcum", "argmax", "argmin", "runner", "N5")):
        if va != vb:
            out["exact_mismatches"].append([k, va, vb])
        continue
    try:
        da, db = Decimal(str(va)), Decimal(str(vb))
    except Exception:
        if va != vb:
            out["exact_mismatches"].append([k, va, vb])
        continue
    d = abs(da - db)
    if kind.endswith("Dreal6"):
        if da != db:
            out["exact_mismatches"].append([k, va, vb])
    cur = out["max_abs_diff_by_kind"].get(kind)
    if cur is None or d > Decimal(cur):
        out["max_abs_diff_by_kind"][kind] = str(d)
out["max_abs_diff_by_kind"] = {k: "%.3e" % float(Decimal(v)) for k, v in out["max_abs_diff_by_kind"].items()}
out["verdict_internal"] = "agree" if not out["exact_mismatches"] and not out["keys_only_in_I"] and not out["keys_only_in_II"] and all(float(v) < 1e-30 for v in out["max_abs_diff_by_kind"].values()) else "DISAGREE"
json.dump(out, open(sys.argv[3], "w"), indent=1)
print(json.dumps(out, indent=1))

