#!/usr/local/bin/python3
"""Diagnostic only: what an IEEE-754 double implementation of A would report for
the sign-count items NF-05(b) and NF-08, where the exact answer is
'PF-2 minus PF-1 > 0 at every cell'. Two natural double variants:
  V1: P_PF2 = -expm1(-x)        V2: P_PF2 = 1 - exp(-x)
with k = n/m (KR-A) or ceil(n/m) (KR-B) as floats and x = 2**(m*k - n)/m!.
"""
import json
import math
import sys

EP2 = [79, 89, 97, 109, 131, 155, 163, 185, 191, 233, 239, 283, 359, 409, 571]


def A(n, m, kr, pf, variant):
    k = n / m if kr == "KR-A" else float(-(-n // m))
    x = 2.0 ** (m * k - n) / math.factorial(m)
    if pf == "PF-1":
        return k - math.log2(x)
    p = -math.expm1(-x) if variant == "V1" else 1.0 - math.exp(-x)
    return k - math.log2(p) if p > 0 else float("inf")


out = {}
for variant in ("V1", "V2"):
    # NF-05(b) at n = 571
    b = {}
    for kr in ("KR-A", "KR-B"):
        diffs = [A(571, m, kr, "PF-2", variant) - A(571, m, kr, "PF-1", variant) for m in range(2, 31)]
        b[kr] = {"positive": sum(1 for d in diffs if d > 0), "non_positive": sum(1 for d in diffs if not d > 0),
                 "m_non_positive": [m for m, d in zip(range(2, 31), diffs) if not d > 0]}
    # NF-08 over EP-2 cells
    below = notb = 0
    for n in EP2:
        for m in range(2, min(30, n) + 1):
            for kr in ("KR-A", "KR-B"):
                if A(n, m, kr, "PF-1", variant) < A(n, m, kr, "PF-2", variant):
                    below += 1
                else:
                    notb += 1
    # float e under KR-A: is m*(n/m) - n exactly zero in double?
    nonzero_e = [m for m in range(2, 31) if (m * (571 / m) - 571) != 0.0]
    nf06 = {}
    for n in (571, 283, 359):
        for kr in ("KR-A", "KR-B"):
            ci = {}
            for pf in ("PF-1", "PF-2"):
                vals = [(A(n, m, kr, pf, variant) + 12 * math.log2(n), m) for m in range(2, 31)]
                bv, bm = vals[0]
                for v, m in vals[1:]:
                    if v < bv:
                        bv, bm = v, m
                ci[pf] = (bv, bm)
            mv = ci["PF-1"][0] - ci["PF-2"][0]
            nf06["n=%d|%s" % (n, kr)] = {"move": mv, "abs_move_exceeds_1e-9": abs(mv) > 1e-9,
                                        "argmin_PF1": ci["PF-1"][1], "argmin_PF2": ci["PF-2"][1]}
    out[variant] = {"NF-05b": b, "NF-08": {"below": below, "not_below": notb}, "NF-06_move": nf06,
                    "KR-A_m_where_float_m_times_n_over_m_minus_n_is_nonzero_at_571": nonzero_e}
json.dump(out, open(sys.argv[1], "w"), indent=1)
print(json.dumps(out, indent=1))

