class Row(dict):
    """A dict emitted as one flow mapping on a single list line."""


# ------------------------------------------------------------------ emitter
SAFE_KEY = re.compile(r"[A-Za-z_][A-Za-z0-9_.\-]*")
RESERVED = {"y", "n", "yes", "no", "on", "off", "true", "false", "null", "~"}
WIDTH = 92


def key_str(k):
    k = str(k)
    if SAFE_KEY.fullmatch(k) and k.lower() not in RESERVED:
        return k
    return json.dumps(k)


def fmt_float(x):
    if math.isnan(x):
        return ".nan"
    if math.isinf(x):
        return ".inf" if x > 0 else "-.inf"
    r = repr(float(x))
    if "e" in r:
        mant, exp = r.split("e")
        if "." not in mant:
            mant += ".0"
        if exp[0] not in "+-":
            exp = "+" + exp
        return mant + "e" + exp
    if "." not in r:
        r += ".0"
    return r


def needs_fold(s):
    return (": " in s) or (" #" in s) or (len(s) > 70 and " " in s)


def scalar(v, in_flow=False):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return fmt_float(v)
    if isinstance(v, str):
        assert "\n" not in v
        if in_flow:
            assert ": " not in v, ("prose with colon-space in flow context", v)
        return json.dumps(v)
    raise TypeError(type(v))


def flow(v):
    if isinstance(v, dict):
        return "{" + ", ".join("%s: %s" % (key_str(k), flow(x)) for k, x in v.items()) + "}"
    if isinstance(v, (list, tuple)):
        return "[" + ", ".join(flow(x) for x in v) + "]"
    return scalar(v, in_flow=True)


def wrap(s, col):
    assert s == s.strip() and "  " not in s and "\n" not in s and "\t" not in s, repr(s[:80])
    words = s.split(" ")
    lines, cur = [], ""
    for w in words:
        if cur and len(cur) + 1 + len(w) + col > WIDTH:
            lines.append(cur)
            cur = w
        else:
            cur = w if not cur else cur + " " + w
    lines.append(cur)
    return lines


def is_simple_list(v):
    return all(not isinstance(x, (dict, list, tuple)) and not (isinstance(x, str) and needs_fold(x)) for x in v)


def emit_kv(prefix, k, v, key_col, out):
    ks = key_str(k)
    if isinstance(v, Row):
        out.append("%s%s: %s" % (prefix, ks, flow(v)))
    elif isinstance(v, dict):
        if not v:
            out.append("%s%s: {}" % (prefix, ks))
        else:
            out.append("%s%s:" % (prefix, ks))
            for k2, v2 in v.items():
                emit_kv(" " * (key_col + 2), k2, v2, key_col + 2, out)
    elif isinstance(v, (list, tuple)):
        if not v:
            out.append("%s%s: []" % (prefix, ks))
        elif is_simple_list(v) and len(flow(v)) + key_col < 140:
            out.append("%s%s: %s" % (prefix, ks, flow(v)))
        else:
            out.append("%s%s:" % (prefix, ks))
            emit_list(v, key_col + 2, out)
    elif isinstance(v, str) and needs_fold(v):
        out.append("%s%s: >-" % (prefix, ks))
        for line in wrap(v, key_col + 2):
            out.append(" " * (key_col + 2) + line)
    else:
        out.append("%s%s: %s" % (prefix, ks, scalar(v)))


def emit_list(lst, col, out):
    for item in lst:
        if isinstance(item, Row):
            out.append(" " * col + "- " + flow(item))
        elif isinstance(item, dict):
            first = True
            for k, v in item.items():
                prefix = (" " * col + "- ") if first else " " * (col + 2)
                emit_kv(prefix, k, v, col + 2, out)
                first = False
        elif isinstance(item, (list, tuple)):
            out.append(" " * col + "- " + flow(item))
        elif isinstance(item, str) and needs_fold(item):
            out.append(" " * col + "- >-")
            for line in wrap(item, col + 2):
                out.append(" " * (col + 2) + line)
        else:
            out.append(" " * col + "- " + scalar(item))


def emit_doc(obj, header):
    out = list(header)
    for k, v in obj.items():
        emit_kv("", k, v, 0, out)
    return "\n".join(out) + "\n"


def plain(o):
    if isinstance(o, dict):
        return {str(k): plain(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)):
        return [plain(x) for x in o]
    return o


def lint_list_item_keys(text):
    """A mapping key may not sit at the indent of the '- ' that opened its item."""
    bad = []
    lines = text.split("\n")
    stack = []  # indents of open '- ' items
    for i, ln in enumerate(lines):
        if not ln.strip() or ln.lstrip().startswith("#"):
            continue
        ind = len(ln) - len(ln.lstrip(" "))
        body = ln.strip()
        if body.startswith("- "):
            continue
        if re.match(r'^("[^"]*"|[A-Za-z_][A-Za-z0-9_.\-]*):( |$)', body):
            # nearest previous non-empty line with indent <= ind
            j = i - 1
            while j >= 0:
                pl = lines[j]
                if pl.strip():
                    pind = len(pl) - len(pl.lstrip(" "))
                    if pind <= ind:
                        if pl.strip().startswith("- ") and pind == ind:
                            bad.append(i + 1)
                        break
                j -= 1
    return bad


