scripts_inline.qx_boundary_scan:
import math
from mpmath import mp, mpf, log
mp.dps = 60
L = log(571, 2)
def W(n, D): return log(mpf(sum(math.comb(n, d) for d in range(D + 1))), 2)
def n5(m, kr):
    k = 571 / m if kr == 'A' else -(-571 // m)
    return round((m - 2) * 571 + m * k)
rows = []
for m in range(2, 31):
    for kr in 'AB':
        N = n5(m, kr)
        dl = {D: (W(N, D) - W(N, 4)) - (D - 4) * L for D in range(4, 65)}
        g = {D: W(N, D) - W(N, D - 1) - L for D in range(5, 65)}
        mind = min((abs(dl[D]), D) for D in range(5, 65))
        ming = min((abs(g[D]), D) for D in range(5, 65))
        rows.append((m, kr, N, float(mind[0]), mind[1], float(ming[0]), ming[1]))
print("cells with |DELTA7(D)| < 0.05 for some D in 5..64 (value, D):")
for r in rows:
    if r[3] < 0.05: print("  m=%d KR-%s N5=%d  min|DELTA7|=%.6f at D=%d" % (r[0], r[1], r[2], r[3], r[4]))
print("cells with |per-step growth - log2 571| < 0.01 for some D (value, D):")
for r in rows:
    if r[5] < 0.01: print("  m=%d KR-%s N5=%d  min|g-log2 571|=%.6f at D=%d" % (r[0], r[1], r[2], r[5], r[6]))
for m in (29, 30):
    for kr in 'AB':
        N = n5(m, kr)
        print("m=%d KR-%s DELTA7(62..64):" % (m, kr), [round(float((W(N, D) - W(N, 4)) - (D - 4) * L), 6) for D in (62, 63, 64)])

